def dih_orbit(s):
    # canonical min over 8 dihedral variants (rotations + flips) represented as flattened tuples
    cur=np.array(s); best=None
    for k in range(4):
        r_=np.rot90(cur,k)
        for v in [r_, r_[:,::-1]]:
            t=tuple(map(tuple,v))
            if best is None or t<best: best=t
    return best
